INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20JP3HR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the number of weeks since a plant was potted ($x$) and its height in centimeters ($y$). The line of best fit is $y = 2.3x + 5.8$. Which of the following is the best interpretation of the slope of this line?', NULL, $lyceon_json$[{"key":"A","text":"The predicted height of the plant increases by $2.3$ centimeters for each additional week after potting."},{"key":"B","text":"The predicted height of the plant increases by $5.8$ centimeters for each additional week after potting."},{"key":"C","text":"The predicted height of the plant when it was first potted was $2.3$ centimeters."},{"key":"D","text":"For every $2.3$-centimeter increase in height, the plant has been growing for one additional week."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of a linear model represents the predicted change in $y$ for each unit increase in $x$. Here, the slope $2.3$ means the plant''s predicted height increases by $2.3$ centimeters for each additional week. The interpretation that height increases by $5.8$ centimeters per week confuses the slope with the $y$-intercept. The claim that the initial height was $2.3$ centimeters confuses the slope with the $y$-intercept in the opposite direction. The statement that each $2.3$-centimeter increase corresponds to one week reverses the independent and dependent variables.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM223O30S', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a length of $23$ feet and a width of $11$ feet. What is the area of the garden, in square feet?', NULL, $lyceon_json$[{"key":"A","text":"$34$"},{"key":"B","text":"$68$"},{"key":"C","text":"$253$"},{"key":"D","text":"$264$"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a rectangle is length times width: $23 \\times 11 = 253$ square feet. The answer $68$ is the perimeter of the rectangle ($2 \\times 23 + 2 \\times 11 = 68$), which confuses perimeter with area. The answer $34$ is the semi-perimeter ($23 + 11 = 34$), an incomplete version of the perimeter calculation. The answer $264$ comes from a multiplication error, likely computing $24 \\times 11$ instead of $23 \\times 11$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM237AP8H', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $9x + 4y = 52$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$\\frac{52}{9}$"},{"key":"C","text":"$13$"},{"key":"D","text":"$-13$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $13$. The $y$-intercept occurs when $x = 0$. Substituting gives $4y = 52$, so $y = 13$. The value $4$ results from misreading the coefficient of $y$ as the intercept value. The value $\\frac{52}{9}$ comes from setting $y = 0$ instead of $x = 0$, which finds the $x$-intercept rather than the $y$-intercept. The value $-13$ results from a sign error when dividing $52$ by $4$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23M4N0L', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'What is the value of $y$ in the solution to the system of equations below?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24RKXOB', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A store sells two types of notebooks. A spiral notebook costs $\\$4$ and a composition notebook costs $\\$7$. A teacher buys $13$ notebooks for a total of $\\$67$. How many composition notebooks did the teacher buy?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$8$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $s$ be the number of spiral notebooks and $c$ be the number of composition notebooks. The system is $s + c = 13$ and $4s + 7c = 67$. From the first equation, $s = 13 - c$. Substituting: $4(13 - c) + 7c = 67$, so $52 - 4c + 7c = 67$, giving $3c = 15$ and $c = 5$. The value $8$ is the number of spiral notebooks, not composition notebooks. The value $3$ results from setting up the cost equation incorrectly, such as swapping the prices. The value $10$ comes from misreading which quantity the question asks for or an arithmetic error in the substitution step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25BIEXE', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'grid_in', E'The function $h(x) = a(x - 3)^2 - 5$ has a minimum value of $-5$ and passes through the point $(7, 27)$. What is the value of $a$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2', ARRAY['2'], E'Since $h(x) = a(x - 3)^2 - 5$ is in vertex form, the vertex is at $(3, -5)$, which gives the minimum value of $-5$ when $a > 0$. To find $a$, substitute the point $(7, 27)$: $27 = a(7 - 3)^2 - 5$, so $27 = 16a - 5$, giving $32 = 16a$ and $a = 2$. A common error is forgetting to subtract $5$ on the right side, which would give $a = \\frac{27}{16}$. Another error is computing $(7 - 3)^2$ as $8$ instead of $16$, which would yield $a = 4$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26E9RN5', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'A line is perpendicular to $5x - 3y = 21$ and passes through the point $(-4, 7)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{23}{5}$"},{"key":"B","text":"$\\frac{23}{5}$"},{"key":"C","text":"$\\frac{47}{5}$"},{"key":"D","text":"$\\frac{41}{3}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $\\frac{23}{5}$. Rewriting the given line in slope-intercept form: $5x - 3y = 21$ becomes $y = \\frac{5}{3}x - 7$, so the slope is $\\frac{5}{3}$. The perpendicular slope is $-\\frac{3}{5}$. Using point-slope form with $(-4, 7)$: $y - 7 = -\\frac{3}{5}(x + 4)$, giving $y = -\\frac{3}{5}x - \\frac{12}{5} + 7 = -\\frac{3}{5}x + \\frac{23}{5}$. The $y$-intercept is $\\frac{23}{5}$. The value $-\\frac{23}{5}$ comes from a sign error when combining $-\\frac{12}{5} + \\frac{35}{5}$, incorrectly getting $-\\frac{23}{5}$. The value $\\frac{47}{5}$ results from dropping the negative sign on the perpendicular slope, using $\\frac{3}{5}$ instead of $-\\frac{3}{5}$, which gives $y = \\frac{3}{5}x + \\frac{12}{5} + 7 = \\frac{3}{5}x + \\frac{47}{5}$. The value $\\frac{41}{3}$ results from using the original slope $\\frac{5}{3}$ (a parallel line) instead of the perpendicular slope, giving $y = \\frac{5}{3}x + \\frac{41}{3}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27T92F6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A university researcher wants to determine whether a new tutoring method improves exam scores more than the standard method. She recruits $70$ volunteers from an introductory biology course and allows them to choose which tutoring method they prefer. After $6$ weeks, the group using the new method scores an average of $11$ points higher on the final exam. A reporter writes: "The new tutoring method has been proven to raise biology exam scores by $11$ points for college students." Which of the following identifies ALL the flaws in the reporter''s claim?', NULL, $lyceon_json$[{"key":"A","text":"Self-selection bias prevents a causal conclusion, and the sample of volunteers from one course cannot be generalized to all college students."},{"key":"B","text":"The sample size is too small to draw any conclusions, and the $11$-point difference may not be statistically significant."},{"key":"C","text":"Self-selection bias prevents a causal conclusion, but the results can be generalized to all college students because volunteers were used."},{"key":"D","text":"The study is flawed only because it lacked a placebo group; the self-selection does not affect validity."}]$lyceon_json$::jsonb, 'A', NULL, E'The reporter''s claim has two distinct flaws. First, because participants chose their own tutoring method rather than being randomly assigned, self-selection bias makes a causal conclusion unsupported -- students who chose the new method may differ systematically from those who chose the standard method. Second, the sample consists of volunteers from a single introductory biology course, not a random sample of all college students, so generalizing to all college students is not warranted. The claim that the sample size is too small is not the primary issue; $70$ participants can yield meaningful results if the study design is sound. Stating that volunteers enable generalization reverses the logic -- volunteer samples are typically less generalizable, not more. Claiming the only flaw is a missing placebo ignores the fundamental problem of self-selection and misunderstands the role of a placebo in a tutoring study.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM285N8T8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'The line of best fit for a set of data is $y = 3x + 14$. According to this model, what is the predicted value of $y$ when $x = 9$?', NULL, $lyceon_json$[{"key":"A","text":"$27$"},{"key":"B","text":"$41$"},{"key":"C","text":"$126$"},{"key":"D","text":"$23$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 9$ into the equation gives $y = 3(9) + 14 = 27 + 14 = 41$. The result $27$ comes from computing only $3 \\times 9$ and omitting the constant $14$. The result $126$ comes from multiplying $9 \\times 14$, misinterpreting the equation structure. The result $23$ comes from adding $9 + 14$ without applying the coefficient.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28GLV3F', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'grid_in', E'The line of best fit for a data set is $y = -1.4x + 89$. One of the data points in the set is $(11, 76.2)$. What is the residual for this data point?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2.6', ARRAY['13/5', '2.6'], E'The predicted value at $x = 11$ is $y = -1.4(11) + 89 = -15.4 + 89 = 73.6$. The residual is the observed value minus the predicted value: $76.2 - 73.6 = 2.6$. A positive residual indicates the actual value is above the line of best fit. A common error is computing the residual as predicted minus observed, which would give $-2.6$ (a sign error). Another error is substituting $x$ incorrectly into the equation, for instance computing $-1.4 + 11 \\times 89$ instead of $-1.4 \\times 11 + 89$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28II13Z', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A delivery service charges a flat fee of $\\$11$ plus $\\$3$ per pound for shipping a package. If a customer has at most $\\$47$ to spend on shipping, which inequality represents the maximum number of pounds $p$ the package can weigh?', NULL, $lyceon_json$[{"key":"A","text":"$3p + 11 \\leq 47$"},{"key":"B","text":"$3p + 11 \\geq 47$"},{"key":"C","text":"$11p + 3 \\leq 47$"},{"key":"D","text":"$3p - 11 \\leq 47$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is $\\$3$ per pound times $p$ pounds plus the $\\$11$ flat fee, giving $3p + 11$. Since the customer can spend at most $\\$47$, the cost must be less than or equal to $47$, so the correct inequality is $3p + 11 \\leq 47$. The choice $3p + 11 \\geq 47$ reverses the direction of the inequality, misinterpreting "at most" as "at least." The choice $11p + 3 \\leq 47$ swaps the per-pound rate and the flat fee. The choice $3p - 11 \\leq 47$ incorrectly subtracts the flat fee instead of adding it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM298ZTUM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A research team randomly assigns $90$ participants to three groups of $30$. Group $1$ receives a new supplement, Group $2$ receives an existing supplement, and Group $3$ receives a placebo. After $8$ weeks, Group $1$ shows significantly greater improvement in endurance than the other two groups. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The new supplement likely causes greater endurance improvement compared to both the existing supplement and placebo."},{"key":"B","text":"The new supplement is associated with greater endurance improvement, but causation cannot be established."},{"key":"C","text":"The results apply to all adults because the study used random assignment."},{"key":"D","text":"The placebo group proves that supplements in general have no effect on endurance."}]$lyceon_json$::jsonb, 'A', NULL, E'Because participants were randomly assigned to groups, this is a controlled experiment, and a causal conclusion is appropriate. The new supplement likely causes the observed improvement in endurance. Claiming only an association without causation incorrectly applies the limitation of observational studies to a randomized experiment. Generalizing the results to all adults confuses random assignment (which supports causal inference) with random sampling (which supports generalization). The placebo group serves as a baseline for comparison, not as evidence that supplements in general are ineffective.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29SP2L2', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'Two independent random samples are taken from voters in a county. Sample $1$ ($n = 400$) finds $52\\%$ favor Proposition $K$, with a margin of error of $\\pm 3\\%$. Sample $2$ ($n = 1{,}100$) finds $48\\%$ favor Proposition $K$, with a margin of error of $\\pm 2\\%$. Which of the following statements is best supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"Sample $1$ is more reliable because it found higher support."},{"key":"B","text":"The confidence intervals from the two samples overlap, so the results are consistent with each other."},{"key":"C","text":"Since the two samples disagree, neither can be used to draw conclusions about the population."},{"key":"D","text":"Sample $2$ proves that fewer than half the voters favor Proposition $K$."}]$lyceon_json$::jsonb, 'B', NULL, E'Sample $1$ gives a confidence interval of $49\\%$ to $55\\%$, and Sample $2$ gives a confidence interval of $46\\%$ to $50\\%$. These intervals overlap (both include values near $49\\%$-$50\\%$), so the results are consistent with each other; the apparent difference could be due to sampling variability. The claim that Sample $1$ is more reliable because of higher support confuses the estimate''s magnitude with its precision. Stating that neither sample can be used because they disagree misunderstands how overlapping intervals indicate compatibility. Saying Sample $2$ proves fewer than half favor the proposition incorrectly treats a confidence interval that includes $50\\%$ as definitive evidence against majority support.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AG8EVD', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $ABC$, point $D$ lies on side $\\overline{BC}$ such that $\\overline{AD}$ bisects $\\angle BAC$. If $\\angle ABC = 47°$ and $\\angle ACB = 29°$, what is the measure of $\\angle ADC$, in degrees?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '99', ARRAY['99'], E'First, find $\\angle BAC$ using the Triangle Angle Sum Theorem: $\\angle BAC = 180° - 47° - 29° = 104°$. Since $\\overline{AD}$ bisects $\\angle BAC$, each half-angle is $\\frac{104°}{2} = 52°$. In particular, $\\angle DAC = 52°$. Now in triangle $ADC$, applying the angle sum: $\\angle ADC = 180° - \\angle DAC - \\angle ACD = 180° - 52° - 29° = 99°$. A common error is forgetting to bisect angle $A$, which would give $\\angle ADC = 180° - 104° - 29° = 47°$. Another error is computing the supplement of $99°$ to get $81°$, which is actually $\\angle ADB$, the angle on the other side of point $D$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AIX2ZB', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'For $x \\neq 0$, which expression is equivalent to $\\frac{(2x + 5)^2 - 25}{4x}$?', NULL, $lyceon_json$[{"key":"A","text":"$x - 5$"},{"key":"B","text":"$x + 5$"},{"key":"C","text":"$x^2 + 5x$"},{"key":"D","text":"$2x + 5$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $x + 5$. Expand the numerator: $(2x + 5)^2 - 25 = 4x^2 + 20x + 25 - 25 = 4x^2 + 20x$. Factor: $4x^2 + 20x = 4x(x + 5)$. Divide by $4x$: $\\frac{4x(x + 5)}{4x} = x + 5$. The result $x - 5$ arises from a sign error when expanding or simplifying. The result $x^2 + 5x$ comes from factoring the numerator as $4x(x + 5)$ but then dividing only by $4$ instead of the full denominator $4x$. The result $2x + 5$ reflects incorrectly canceling $\\frac{(2x+5)^2}{(2x+5)}$ while mishandling the $-25$ and the denominator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AU6WD4', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'grid_in', E'The system of equations $6x - 5y = 38$ and $4x + 3y = 0$ has a solution $(x, y)$. What is the value of $x + y$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-1', ARRAY['-1'], E'To solve the system, multiply $6x - 5y = 38$ by $3$ and $4x + 3y = 0$ by $5$ to align the $y$-coefficients: $18x - 15y = 114$ and $20x + 15y = 0$. Adding these equations gives $38x = 114$, so $x = 3$. Substituting into $4(3) + 3y = 0$ gives $12 + 3y = 0$, so $3y = -12$ and $y = -4$. Therefore $x + y = 3 + (-4) = -1$. A common error is to find $x = 3$ but forget to solve for $y$, or to make a sign error when computing $3 + (-4)$ and obtain $1$ instead of $-1$. Another error is to subtract the equations instead of adding, leading to an incorrect value of $x$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AX7QMF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $9$. What is the area of a sector of this circle with a central angle of $80°$?', NULL, $lyceon_json$[{"key":"A","text":"$4\\pi$"},{"key":"B","text":"$18\\pi$"},{"key":"C","text":"$36\\pi$"},{"key":"D","text":"$81\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a sector is $\\frac{\\theta}{360°} \\times \\pi r^2$. Substituting: $\\frac{80}{360} \\times \\pi(9)^2 = \\frac{2}{9} \\times 81\\pi = 18\\pi$. The answer $4\\pi$ results from computing the arc length instead of the sector area: $\\frac{80}{360} \\times 2\\pi(9) = 4\\pi$. The answer $36\\pi$ comes from dividing the angle by $180°$ instead of $360°$: $\\frac{80}{180} \\times 81\\pi \\approx 36\\pi$. The answer $81\\pi$ is the area of the entire circle, omitting the fractional multiplier for the sector.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CPXVPZ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = x^2 - 7$. What is the value of $g(11)$?', NULL, $lyceon_json$[{"key":"A","text":"$114$"},{"key":"B","text":"$128$"},{"key":"C","text":"$4$"},{"key":"D","text":"$-114$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $114$. Substituting $x = 11$ into $g(x) = x^2 - 7$ gives $g(11) = 11^2 - 7 = 121 - 7 = 114$. The result $128$ comes from adding $7$ to $121$ instead of subtracting. The result $4$ comes from computing $11 - 7 = 4$ without squaring the input first. The result $-114$ arises from incorrectly applying a negative sign to the entire expression.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DQA081', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'If $-4 < 2x + 9 \\leq 17$, what is the greatest integer value of $x$ that satisfies this compound inequality?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Start with the compound inequality $-4 < 2x + 9 \\leq 17$. Subtract $9$ from all three parts: $-4 - 9 < 2x \\leq 17 - 9$, which simplifies to $-13 < 2x \\leq 8$. Divide all parts by $2$: $-6.5 < x \\leq 4$. The greatest integer value of $x$ satisfying $x \\leq 4$ is $4$. A common error is to find $x < 4$ by mishandling the non-strict inequality, which would give $3$. Another error is to solve only one part of the compound inequality, such as finding $x \\leq 4$ without checking that $x > -6.5$ is also required.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G4ZW12', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $3x^2 \\cdot 7x^3$?', NULL, $lyceon_json$[{"key":"A","text":"$10x^5$"},{"key":"B","text":"$21x^5$"},{"key":"C","text":"$21x^6$"},{"key":"D","text":"$10x^6$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $21x^5$. To multiply monomials, multiply the coefficients ($3 \\times 7 = 21$) and add the exponents of like bases ($x^2 \\cdot x^3 = x^{2+3} = x^5$). The result $10x^5$ comes from adding the coefficients instead of multiplying them. The result $21x^6$ comes from multiplying the exponents ($2 \\times 3 = 6$) instead of adding them. The result $10x^6$ combines both errors.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GLNDJF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A machine fills $7$ bottles every $4$ minutes. At this rate, how many bottles does the machine fill in $28$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$35$"},{"key":"B","text":"$42$"},{"key":"C","text":"$49$"},{"key":"D","text":"$32$"}]$lyceon_json$::jsonb, 'C', NULL, E'The rate is $\\frac{7 \\text{ bottles}}{4 \\text{ minutes}}$. Since $28 \\div 4 = 7$ intervals, the machine fills $7 \\times 7 = 49$ bottles. The result $35$ comes from computing $7 \\times 5$ due to an arithmetic slip in determining the number of intervals. The result $42$ arises from incorrectly using $6$ intervals instead of $7$. The result $32$ comes from adding $28 + 4$ rather than using the proportional relationship.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HDRV6Q', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Lines $p$ and $q$ are parallel, and line $t$ is a transversal that intersects both lines. If one of the angles formed at the intersection of line $p$ and line $t$ measures $119°$, what is the measure, in degrees, of the co-interior angle on the same side of the transversal at the intersection of line $q$ and line $t$?', NULL, $lyceon_json$[{"key":"A","text":"$29°$"},{"key":"B","text":"$61°$"},{"key":"C","text":"$71°$"},{"key":"D","text":"$119°$"}]$lyceon_json$::jsonb, 'B', NULL, E'Co-interior angles (also called same-side interior or consecutive interior angles) formed by parallel lines and a transversal are supplementary, meaning they sum to $180°$. The co-interior angle is $180° - 119° = 61°$. The answer $119°$ results from incorrectly treating co-interior angles as equal, which applies to corresponding or alternate interior angles, not co-interior angles. The answer $29°$ comes from subtracting from $90°$ instead of $180°$, confusing supplementary with complementary. The answer $71°$ reflects an arithmetic error in subtracting from $180°$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HDZBHI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'A store marks up a wholesale item by $40\\%$ to set its retail price. During a clearance event, the retail price is then discounted by $25\\%$. If the clearance price of the item is $\\$63$, what was the wholesale price, in dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '60', ARRAY['60'], E'Let $w$ be the wholesale price. The retail price after a $40\\%$ markup is $1.40w$. The clearance price after a $25\\%$ discount is $0.75 \\times 1.40w = 1.05w$. Setting $1.05w = 63$ gives $w = \\frac{63}{1.05} = 60$. A common error is treating the net effect as $40\\% - 25\\% = 15\\%$ and computing $\\frac{63}{1.15} \\approx 54.78$, which incorrectly assumes percentage changes are additive. Another error is dividing $63$ by $0.75$ first and then by $1.40$, getting the order of operations right but making an arithmetic slip along the way.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I77L9G', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'The line $y = \\frac{3}{4}x + k$ is tangent to the circle $(x - 3)^2 + (y + 2)^2 = 100$. If $k > 0$, what is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '33/4', ARRAY['33/4', '8.25'], E'The circle has center $(3, -2)$ and radius $10$. For the line $y = \\frac{3}{4}x + k$, rewrite as $3x - 4y + 4k = 0$ (multiplying through by $4$). The distance from the center $(3, -2)$ to this line is $\\frac{|3(3) - 4(-2) + 4k|}{\\sqrt{9 + 16}} = \\frac{|9 + 8 + 4k|}{5} = \\frac{|17 + 4k|}{5}$. For tangency, this distance equals the radius: $\\frac{|17 + 4k|}{5} = 10$, so $|17 + 4k| = 50$. This gives $17 + 4k = 50$ or $17 + 4k = -50$. Solving: $4k = 33$ (giving $k = \\frac{33}{4}$) or $4k = -67$ (giving $k = -\\frac{67}{4}$). Since $k > 0$, the answer is $k = \\frac{33}{4}$. A common error is forgetting to multiply the entire equation by $4$ before applying the distance formula, leading to an incorrect denominator. Another error is using the distance as $r^2 = 100$ instead of $r = 10$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LS7TVB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'In a survey of $200$ employees, $85$ commute by car, $53$ commute by train, $37$ commute by bus, and the rest bike. Of those who commute by train, $19$ also work remotely at least once per week. What is the probability that a randomly selected employee who commutes by train also works remotely at least once per week?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{19}{200}$"},{"key":"B","text":"$\\frac{19}{53}$"},{"key":"C","text":"$\\frac{53}{200}$"},{"key":"D","text":"$\\frac{19}{85}$"}]$lyceon_json$::jsonb, 'B', NULL, E'This is a conditional probability question. Given that an employee commutes by train, the relevant pool is the $53$ train commuters, not all $200$ employees. Of those $53$, $19$ work remotely at least once per week, so the conditional probability is $\\frac{19}{53}$. The answer $\\frac{19}{200}$ incorrectly uses the entire employee pool as the denominator rather than conditioning on train commuters. The answer $\\frac{53}{200}$ gives the probability of being a train commuter, not of working remotely given train commuting. The answer $\\frac{19}{85}$ mistakenly uses the number of car commuters as the denominator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MF1PIK', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'The system of equations $y = x^2 + 3x - 7$ and $y = 5x + k$ has exactly one real solution. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$8$"},{"key":"B","text":"$-8$"},{"key":"C","text":"$-7$"},{"key":"D","text":"$-32$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $-8$. Setting the two expressions for $y$ equal gives $x^2 + 3x - 7 = 5x + k$, which simplifies to $x^2 - 2x - 7 - k = 0$. For the system to have exactly one real solution, the discriminant of this quadratic must equal zero. The discriminant is $(-2)^2 - 4(1)(-7 - k) = 4 + 28 + 4k = 32 + 4k$. Setting $32 + 4k = 0$ gives $k = -8$. The result $8$ comes from a sign error when solving $4k = -32$. The result $-7$ comes from extracting the constant term of the original quadratic without completing the discriminant analysis. The result $-32$ comes from omitting the division by $4$ when solving $4k = -32$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MMFGV8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'What is the radius of the circle defined by the equation $x^2 + y^2 - 14x + 6y + 42 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$7$"},{"key":"C","text":"$16$"},{"key":"D","text":"$\\sqrt{42}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Complete the square for both variables. Rewrite: $(x^2 - 14x) + (y^2 + 6y) = -42$. Completing the square: $(x^2 - 14x + 49) + (y^2 + 6y + 9) = -42 + 49 + 9$, which simplifies to $(x - 7)^2 + (y + 3)^2 = 16$. Since $r^2 = 16$, the radius is $r = 4$. The answer $16$ results from identifying $r^2 = 16$ but failing to take the square root. The answer $7$ comes from taking half the coefficient of $x$ and mistaking it for the radius rather than the $x$-coordinate of the center. The answer $\\sqrt{42}$ incorrectly uses the constant term $42$ as $r^2$ without completing the square.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N3GTYN', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $49a^2 - 64b^2$?', NULL, $lyceon_json$[{"key":"A","text":"$(7a - 8b)^2$"},{"key":"B","text":"$(7a - 8b)(7a + 8b)$"},{"key":"C","text":"$7(a - 8b)(a + 8b)$"},{"key":"D","text":"$(49a - 8b)(a + 8b)$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $(7a - 8b)(7a + 8b)$. The expression $49a^2 - 64b^2$ is a difference of two squares, since $49a^2 = (7a)^2$ and $64b^2 = (8b)^2$. Applying the identity $A^2 - B^2 = (A - B)(A + B)$ gives $(7a - 8b)(7a + 8b)$. The choice $(7a - 8b)^2$ expands to $49a^2 - 112ab + 64b^2$, which includes a middle term and has the wrong sign on the last term. The choice $7(a - 8b)(a + 8b)$ incorrectly factors out $7$ from only one squared term, yielding $7(a^2 - 64b^2) = 7a^2 - 448b^2$. The choice $(49a - 8b)(a + 8b)$ fails to take the square root of $49a^2$ and expands to $49a^2 + 392ab - 8ab - 64b^2$, which includes cross terms not present in the original.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NCDSXF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one leg measures $11$ and the hypotenuse measures $\\sqrt{170}$. What is the length of the other leg?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$7$"},{"key":"C","text":"$49$"},{"key":"D","text":"$\\sqrt{291}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Using the Pythagorean theorem, $a^2 + 11^2 = (\\sqrt{170})^2$, which gives $a^2 + 121 = 170$, so $a^2 = 49$ and $a = 7$. The answer $49$ comes from stopping at $a^2 = 49$ without taking the square root. The answer $\\sqrt{291}$ results from adding instead of subtracting: $170 + 121 = 291$. The answer $3$ comes from a computational error in evaluating $\\sqrt{49}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NOSCJI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally costs $\\$85$. If the price is reduced by $20\\%$, what is the sale price of the jacket?', NULL, $lyceon_json$[{"key":"A","text":"$\\$65$"},{"key":"B","text":"$\\$17$"},{"key":"C","text":"$\\$68$"},{"key":"D","text":"$\\$102$"}]$lyceon_json$::jsonb, 'C', NULL, E'A $20\\%$ reduction on $\\$85$ is $0.20 \\times 85 = \\$17$, so the sale price is $85 - 17 = \\$68$. The result $\\$65$ comes from subtracting $20$ from $85$ instead of computing $20\\%$ of $85$. The result $\\$17$ is the discount amount itself, not the sale price. The result $\\$102$ comes from adding $20\\%$ to the original price instead of subtracting it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OJG8UF', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'If $x^2 = 169$ and $x > 0$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'The equation $x^2 = 169$ has two solutions: $x = 13$ and $x = -13$, since $13^2 = 169$ and $(-13)^2 = 169$. Because the problem specifies $x > 0$, the answer is $13$. A common error is giving $-13$, which satisfies the equation but violates the condition $x > 0$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q40WDQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set consists of the values $5, 11, 13, 19, 23, 37$. What is the median of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$13$"},{"key":"B","text":"$16$"},{"key":"C","text":"$18$"},{"key":"D","text":"$19$"}]$lyceon_json$::jsonb, 'B', NULL, E'With six values sorted as $5, 11, 13, 19, 23, 37$, the median is the average of the 3rd and 4th values: $\\frac{13 + 19}{2} = \\frac{32}{2} = 16$. The result $13$ comes from selecting only the 3rd value without averaging it with the 4th. The result $18$ comes from an arithmetic error when averaging, such as computing $\\frac{13 + 19}{2}$ incorrectly. The result $19$ comes from selecting only the 4th value without averaging.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q70DJX', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'A ramp makes an angle of $23°$ with the horizontal ground. If the ramp covers a horizontal distance of $17$ feet, which of the following expressions gives the length of the ramp, in feet?', NULL, $lyceon_json$[{"key":"A","text":"$17\\sin(23°)$"},{"key":"B","text":"$\\frac{17}{\\sin(23°)}$"},{"key":"C","text":"$\\frac{17}{\\cos(23°)}$"},{"key":"D","text":"$17\\cos(23°)$"}]$lyceon_json$::jsonb, 'C', NULL, E'The horizontal distance is the side adjacent to the $23°$ angle, and the ramp is the hypotenuse. Using the cosine ratio: $\\cos(23°) = \\frac{\\text{adjacent}}{\\text{hypotenuse}} = \\frac{17}{\\text{ramp length}}$. Solving gives ramp length $= \\frac{17}{\\cos(23°)}$. The expression $\\frac{17}{\\sin(23°)}$ incorrectly uses sine where cosine is needed, confusing adjacent and opposite sides. The expression $17\\cos(23°)$ multiplies by cosine instead of dividing, which would give the adjacent side if $17$ were the hypotenuse. The expression $17\\sin(23°)$ would give the opposite side if $17$ were the hypotenuse.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q9X2LP', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A gym membership costs a one-time enrollment fee plus a fixed monthly rate. The total cost in dollars after $m$ months is modeled by $C(m) = 53m + 79$. What does the value $53$ represent in this function?', NULL, $lyceon_json$[{"key":"A","text":"The one-time enrollment fee in dollars"},{"key":"B","text":"The total cost in dollars after one month"},{"key":"C","text":"The monthly membership rate in dollars"},{"key":"D","text":"The number of months of membership"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is the monthly membership rate in dollars. In the function $C(m) = 53m + 79$, the coefficient $53$ multiplies the number of months $m$, so it represents the rate of change of total cost per month — that is, the monthly membership rate. The enrollment fee is the constant $79$, not $53$, since $79$ is the cost when $m = 0$. The total cost after one month is $C(1) = 53 + 79 = 132$, not $53$ alone. The number of months is the input variable $m$, not the coefficient $53$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QQV5SM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A conical water tank has a radius of $6$ cm at the top and a height of $8$ cm. Water fills the tank to a depth of $4$ cm measured from the vertex of the cone. What fraction of the cone''s total volume is filled with water?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1/8', ARRAY['1/8', '0.125', '.125'], E'Since the water fills the cone from the vertex upward to a depth of $4$ cm, the water forms a smaller cone similar to the full cone. The ratio of heights is $\\frac{4}{8} = \\frac{1}{2}$. By similar triangles, the radius of the water surface is $6 \\times \\frac{1}{2} = 3$ cm. The volume of a cone is $V = \\frac{1}{3}\\pi r^2 h$. The full cone has volume $\\frac{1}{3}\\pi(6)^2(8) = 96\\pi$ cm$^3$. The water cone has volume $\\frac{1}{3}\\pi(3)^2(4) = 12\\pi$ cm$^3$. The fraction filled is $\\frac{12\\pi}{96\\pi} = \\frac{1}{8}$. Alternatively, for similar solids with a linear scale factor of $\\frac{1}{2}$, the volume scales by $\\left(\\frac{1}{2}\\right)^3 = \\frac{1}{8}$. A common error is squaring the ratio instead of cubing it, obtaining $\\frac{1}{4}$. Another error is using $\\frac{1}{2}$ directly without recognizing the cubic relationship between linear dimensions and volume.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QVU241', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'In a school of $850$ students, $60\\%$ participate in at least one extracurricular activity. Of those who participate, $30\\%$ are in two or more activities. How many students are in two or more extracurricular activities?', NULL, $lyceon_json$[{"key":"A","text":"$510$"},{"key":"B","text":"$255$"},{"key":"C","text":"$153$"},{"key":"D","text":"$340$"}]$lyceon_json$::jsonb, 'C', NULL, E'First, $60\\%$ of $850$ is $0.60 \\times 850 = 510$ students who participate in at least one activity. Then $30\\%$ of those $510$ is $0.30 \\times 510 = 153$ students in two or more activities. The result $510$ stops at the first percentage step without applying the second. The result $255$ comes from applying $30\\%$ to the entire school ($0.30 \\times 850$) rather than to the participating subset. The result $340$ arises from an arithmetic error such as computing $850 \\times 0.40$ instead of applying the two percentages sequentially.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S6C9W3', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'A mechanic charges a flat diagnostic fee of $\\$43$ plus $\\$67$ per hour of labor. A second mechanic charges no diagnostic fee but $\\$89$ per hour of labor. For how many hours of labor would a customer pay the same total amount to either mechanic? Express your answer as a fraction.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '43/22', ARRAY['43/22', '1.954', '1.955'], E'Let $h$ represent the number of hours. The first mechanic charges $43 + 67h$ dollars and the second charges $89h$ dollars. Setting these equal gives $43 + 67h = 89h$. Subtracting $67h$ from both sides yields $43 = 22h$, so $h = \\frac{43}{22}$. A common error is setting up the equation as $43 + 67h = 89$ (confusing the hourly rate with a total), which gives $67h = 46$ and $h = \\frac{46}{67}$. Another error is computing $89 - 67 = 22$ correctly but then dividing $22$ by $43$ instead of $43$ by $22$, yielding $\\frac{22}{43}$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S82I2X', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A student''s first five quiz scores are $72, 78, 84, 91$, and $95$. After a sixth quiz, the student''s mean score across all six quizzes is $81$. What was the student''s score on the sixth quiz?', NULL, $lyceon_json$[{"key":"A","text":"$66$"},{"key":"B","text":"$78$"},{"key":"C","text":"$81$"},{"key":"D","text":"$84$"}]$lyceon_json$::jsonb, 'A', NULL, E'The sum of the first five scores is $72 + 78 + 84 + 91 + 95 = 420$. For the mean of six scores to be $81$, the total sum must be $81 \\times 6 = 486$. The sixth score is $486 - 420 = 66$. The result $78$ comes from an arithmetic error in the subtraction. The result $81$ comes from assuming the sixth score equals the desired mean, which is a conceptual misunderstanding. The result $84$ comes from confusing the original mean of the five scores with the sixth score.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S8XPWC', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A right circular cylinder has a radius of $7$ cm and a height of $11$ cm. What is the volume of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$77\\pi \\text{ cm}^3$"},{"key":"B","text":"$154\\pi \\text{ cm}^3$"},{"key":"C","text":"$539\\pi \\text{ cm}^3$"},{"key":"D","text":"$1078\\pi \\text{ cm}^3$"}]$lyceon_json$::jsonb, 'C', NULL, E'The volume of a cylinder is $V = \\pi r^2 h = \\pi(7)^2(11) = \\pi(49)(11) = 539\\pi$ cm$^3$. The answer $77\\pi$ results from using $\\pi r h$ instead of $\\pi r^2 h$: $\\pi(7)(11) = 77\\pi$, failing to square the radius. The answer $154\\pi$ is the lateral surface area $2\\pi r h = 2\\pi(7)(11) = 154\\pi$, confusing surface area with volume. The answer $1078\\pi$ doubles the correct volume, perhaps from mistakenly using $2\\pi r^2 h$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TDTREG', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line passes through the points $(2, 9)$ and $(5, -3)$. What is the $x$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17/4', ARRAY['17/4', '4.25'], E'The slope of the line is $m = \\frac{-3 - 9}{5 - 2} = \\frac{-12}{3} = -4$. Using the point $(2, 9)$ in point-slope form gives $y - 9 = -4(x - 2)$, which simplifies to $y = -4x + 17$. Setting $y = 0$ to find the $x$-intercept: $0 = -4x + 17$, so $4x = 17$ and $x = \\frac{17}{4}$. A common error is finding the $y$-intercept ($17$) instead of the $x$-intercept. Another error is computing the slope with the wrong sign, getting $4$ instead of $-4$, which leads to $y = 4x + 1$ and $x$-intercept $-\\frac{1}{4}$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TIM246', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The function $g$ is defined by $g(x) = \\frac{7x - 19}{3}$. If $g(a) = 2a - 11$, what is the value of $a$?', NULL, $lyceon_json$[{"key":"A","text":"$-14$"},{"key":"B","text":"$-8$"},{"key":"C","text":"$8$"},{"key":"D","text":"$14$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $-14$. Setting $g(a) = 2a - 11$ gives $\\frac{7a - 19}{3} = 2a - 11$. Multiplying both sides by $3$ yields $7a - 19 = 6a - 33$. Subtracting $6a$ from both sides gives $a - 19 = -33$, and adding $19$ to both sides gives $a = -14$. To verify: $g(-14) = \\frac{7(-14) - 19}{3} = \\frac{-117}{3} = -39$, and $2(-14) - 11 = -39$. The value $-8$ comes from an arithmetic slip in computing $-33 + 19$, getting $-8$ instead of $-14$ (as if computing $-19 + 11$). The value $8$ results from failing to distribute the $3$ to the $-11$ term, solving $7a - 19 = 6a - 11$ to get $a = 8$. The value $14$ results from a sign error, producing $a = 14$ instead of $a = -14$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U8HKZP', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following values of $x$ satisfies the inequality $3x - 7 > 14$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$6$"},{"key":"C","text":"$7$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'D', NULL, E'Adding $7$ to both sides of $3x - 7 > 14$ gives $3x > 21$, and dividing both sides by $3$ gives $x > 7$. The value $8$ satisfies this since $8 > 7$. The value $7$ does not satisfy the strict inequality because $7$ is not greater than $7$. The value $6$ results from an arithmetic slip such as dividing $21$ by $3$ incorrectly. The value $5$ reflects a misunderstanding of the inequality''s solution set.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UU6NFJ', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'If $f(x) = 11x - 37$, what is the value of $f(6)$?', NULL, $lyceon_json$[{"key":"A","text":"$-29$"},{"key":"B","text":"$23$"},{"key":"C","text":"$29$"},{"key":"D","text":"$103$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $29$. Substituting $x = 6$ into the function gives $f(6) = 11(6) - 37 = 66 - 37 = 29$. The value $-29$ results from reversing the subtraction order, computing $37 - 66$ instead of $66 - 37$. The value $23$ comes from an arithmetic slip in the multiplication step, computing $11 \\times 6 = 60$ instead of $66$, leading to $60 - 37 = 23$. The value $103$ results from adding $37$ instead of subtracting it, computing $66 + 37 = 103$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VPDQAH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A box contains $6$ orange tokens, $9$ white tokens, and $5$ black tokens. If one token is selected at random, what is the probability that it is white?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{9}{20}$"},{"key":"B","text":"$\\frac{9}{14}$"},{"key":"C","text":"$\\frac{6}{20}$"},{"key":"D","text":"$\\frac{5}{20}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of tokens is $6 + 9 + 5 = 20$. The probability of selecting a white token is the number of white tokens divided by the total: $\\frac{9}{20}$. The fraction $\\frac{9}{14}$ incorrectly excludes the black tokens from the total, counting only orange and white. The fraction $\\frac{6}{20}$ gives the probability of selecting an orange token, misreading which color was asked about. The fraction $\\frac{5}{20}$ gives the probability of selecting a black token.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VRUUWF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A nutritionist observes that people who eat breakfast daily tend to have lower body mass index (BMI) than those who skip breakfast. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Eating breakfast daily causes a lower BMI."},{"key":"B","text":"Skipping breakfast causes a higher BMI."},{"key":"C","text":"There is an association between eating breakfast daily and having a lower BMI."},{"key":"D","text":"People who skip breakfast should start eating breakfast to lower their BMI."}]$lyceon_json$::jsonb, 'C', NULL, E'Since this is an observational study, the nutritionist can only identify an association between breakfast habits and BMI, not a causal relationship. Confounding variables (such as overall lifestyle habits) could explain the difference. Stating that eating breakfast causes lower BMI or that skipping breakfast causes higher BMI both incorrectly infer causation from an observational study. Recommending that people start eating breakfast to lower BMI goes further by prescribing action based on a causal claim that the study design cannot support.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VY9506', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the exterior angle at vertex $R$ measures $138°$. If $\\angle P = 4x + 3$ and $\\angle Q = 2x + 9$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$21$"},{"key":"B","text":"$25$"},{"key":"C","text":"$42$"},{"key":"D","text":"$63$"}]$lyceon_json$::jsonb, 'A', NULL, E'By the Exterior Angle Theorem, the exterior angle of a triangle equals the sum of the two non-adjacent interior angles. Therefore $138 = (4x + 3) + (2x + 9) = 6x + 12$. Solving: $6x = 126$, so $x = 21$. The answer $25$ results from a sign error when combining constants, adding $12$ to $138$ instead of subtracting ($6x = 150$, $x = 25$). The answer $42$ comes from finding the interior angle at $R$ ($180° - 138° = 42°$) and incorrectly reporting that as $x$. The answer $63$ results from dividing $126$ by $2$ instead of $6$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VYNORH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A recipe requires flour and sugar in the ratio $11:3$ by weight. If $a$ pounds of flour and $b$ pounds of sugar are used, and the total weight of flour and sugar together is $5.6$ pounds, what is the value of $a - b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3.2', ARRAY['16/5', '3.2'], E'The ratio of flour to sugar is $11:3$, giving $11 + 3 = 14$ total parts. Each part weighs $\\frac{5.6}{14} = 0.4$ pounds. Therefore $a = 11 \\times 0.4 = 4.4$ pounds and $b = 3 \\times 0.4 = 1.2$ pounds, so $a - b = 4.4 - 1.2 = 3.2$. A common error is computing only $a$ or only $b$ and reporting that as the answer (partial reasoning). Another error is using the ratio $11:14$ or $3:14$ to find $a - b$ directly, which sets up the relationship incorrectly.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W2P6E8', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $x$ in the equation $9x - 23 = 40$?', NULL, $lyceon_json$[{"key":"A","text":"7"},{"key":"B","text":"3"},{"key":"C","text":"9"},{"key":"D","text":"5"}]$lyceon_json$::jsonb, 'A', NULL, E'Adding 23 to both sides gives $9x = 63$. Dividing both sides by 9 gives $x = 7$. The value 3 results from an arithmetic slip when dividing. The value 9 comes from confusing the coefficient with the solution. The value 5 results from a sign error when isolating the variable.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WSM2KL', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = 3 \\cdot 2^x$. If $f(a) = 96$, what is the value of $f(a - 3)$?', NULL, $lyceon_json$[{"key":"A","text":"$93$"},{"key":"B","text":"$12$"},{"key":"C","text":"$32$"},{"key":"D","text":"$768$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $12$. Since $f(a) = 3 \\cdot 2^a = 96$, we can write $f(a - 3) = 3 \\cdot 2^{a-3} = 3 \\cdot 2^a \\cdot 2^{-3} = 96 \\cdot \\frac{1}{8} = 12$. Alternatively, $2^a = 32$ gives $a = 5$, so $f(2) = 3 \\cdot 4 = 12$. The result $93$ comes from subtracting $3$ from $f(a) = 96$, confusing $f(a - 3)$ with $f(a) - 3$. The result $32$ comes from computing $2^a = \\frac{96}{3} = 32$ and stopping there without evaluating $f(a - 3)$. The result $768$ comes from multiplying $96$ by $2^3 = 8$ instead of dividing, misapplying the exponent rule for $2^{a-3}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WUN5ED', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the value of $x$ in the equation $\\frac{5x + 3}{2} - 4 = 13$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{23}{5}$"},{"key":"B","text":"$\\frac{27}{5}$"},{"key":"C","text":"$\\frac{31}{5}$"},{"key":"D","text":"$\\frac{37}{5}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $\\frac{31}{5}$. Adding $4$ to both sides gives $\\frac{5x + 3}{2} = 17$. Multiplying both sides by $2$ gives $5x + 3 = 34$. Subtracting $3$ from both sides gives $5x = 31$, so $x = \\frac{31}{5}$. The value $\\frac{23}{5}$ results from skipping the step of adding $4$, proceeding as if $\\frac{5x+3}{2} = 13$, which gives $5x + 3 = 26$ and $5x = 23$. The value $\\frac{27}{5}$ comes from incorrectly subtracting $4$ from the numerator directly, treating the equation as $\\frac{5x + 3 - 4}{2} = 13$, which yields $5x - 1 = 26$ and $5x = 27$. The value $\\frac{37}{5}$ comes from adding $3$ instead of subtracting it, getting $5x = 37$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WVZG67', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'In quadrilateral $ABCD$, $\\angle B = 90°$ and $\\angle D = 90°$. If $AB = 19$, $BC = 7$, and $CD = 11$, what is the length of $AD$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17', ARRAY['17'], E'Draw diagonal $\\overline{AC}$. Since $\\angle B = 90°$, triangle $ABC$ is a right triangle with legs $AB = 19$ and $BC = 7$. By the Pythagorean theorem, $AC^2 = 19^2 + 7^2 = 361 + 49 = 410$. Since $\\angle D = 90°$, triangle $ACD$ is a right triangle with hypotenuse $\\overline{AC}$ and legs $CD = 11$ and $AD$. Therefore $AD^2 = AC^2 - CD^2 = 410 - 121 = 289$, giving $AD = 17$. A common error is computing $AC = \\sqrt{410} \\approx 20.25$ and then subtracting $11$ directly to get approximately $9.25$, which confuses linear subtraction with the Pythagorean relationship. Another error is forgetting to apply the Pythagorean theorem to the second triangle and instead reporting $\\sqrt{410}$ as the answer.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XKXQ0Y', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A cyclist travels $13$ miles in $52$ minutes. A jogger covers $9$ miles in $54$ minutes. What is the positive difference between their speeds, in miles per hour?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$5$"},{"key":"C","text":"$15$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'B', NULL, E'The cyclist''s speed is $\\frac{13}{52} \\times 60 = 15$ miles per hour. The jogger''s speed is $\\frac{9}{54} \\times 60 = 10$ miles per hour. The positive difference is $15 - 10 = 5$ miles per hour. The result $4$ comes from computing the difference in miles ($13 - 9$) without converting to a per-hour rate. The result $15$ is the cyclist''s speed alone, not the difference. The result $10$ is the jogger''s speed alone, not the difference.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"unit_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z6ZTDP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'A class of $17$ students has a mean test score of $74$. The $9$ highest-scoring students have a mean of $82$. What is the mean score of the remaining $8$ students?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '65', ARRAY['65'], E'The total sum of all $17$ scores is $17 \\times 74 = 1258$. The sum of the $9$ highest scores is $9 \\times 82 = 738$. The sum of the remaining $8$ scores is $1258 - 738 = 520$. The mean of those $8$ students is $\\frac{520}{8} = 65$. A common error is to assume the remaining mean can be found by subtracting the group means ($74 - 82 = -8$), ignoring that the groups have different sizes. Another error is dividing $520$ by $9$ instead of $8$, mixing up the group sizes.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z8UMHT', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'What is the sum of the solutions to $2x^2 - 13x + 21 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{13}{2}$"},{"key":"B","text":"$\\frac{21}{2}$"},{"key":"C","text":"$13$"},{"key":"D","text":"$\\frac{-13}{2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $\\frac{13}{2}$. By Vieta''s formulas, for $ax^2 + bx + c = 0$, the sum of the solutions equals $-\\frac{b}{a}$. Here $a = 2$, $b = -13$, and $c = 21$, so the sum is $-\\frac{-13}{2} = \\frac{13}{2}$. This can be verified: the equation factors as $(2x - 7)(x - 3) = 0$, giving $x = \\frac{7}{2}$ and $x = 3$, and $\\frac{7}{2} + 3 = \\frac{13}{2}$. The result $\\frac{21}{2}$ confuses the sum formula with the product formula $\\frac{c}{a}$. The result $13$ uses $-b$ but omits dividing by $a$. The result $\\frac{-13}{2}$ applies $\\frac{b}{a}$ without negating $b$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZAINL9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A researcher surveys a random sample of $150$ residents of a city and finds that $63\\%$ support a new recycling initiative. The margin of error is $\\pm 4\\%$. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $63\\%$ of all city residents support the initiative."},{"key":"B","text":"Between $59\\%$ and $67\\%$ of the sampled residents support the initiative."},{"key":"C","text":"It is plausible that between $59\\%$ and $67\\%$ of all city residents support the initiative."},{"key":"D","text":"No more than $67\\%$ of all city residents could support the initiative."}]$lyceon_json$::jsonb, 'C', NULL, E'A margin of error applied to a sample statistic produces a confidence interval for the population parameter. Since the sample proportion is $63\\%$ with a margin of error of $\\pm 4\\%$, it is plausible that the true proportion of all city residents who support the initiative is between $59\\%$ and $67\\%$. Saying exactly $63\\%$ ignores the sampling variability that the margin of error addresses. The interpretation that the interval applies to the sampled residents confuses the sample data (which is known) with the inference about the population. Claiming no more than $67\\%$ could support it treats the upper bound as a ceiling rather than one end of a plausible range.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZNHZP0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A school has $340$ students. Of these, $142$ play a sport and $113$ are in a music program. There are $47$ students who both play a sport and are in a music program. If a student is selected at random from those who play a sport OR are in a music program (or both), what is the probability that the student is in both?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{47}{340}$"},{"key":"B","text":"$\\frac{47}{255}$"},{"key":"C","text":"$\\frac{47}{208}$"},{"key":"D","text":"$\\frac{47}{162}$"}]$lyceon_json$::jsonb, 'C', NULL, E'By the inclusion-exclusion principle, the number of students who play a sport or are in a music program is $142 + 113 - 47 = 208$. Of these $208$ students, $47$ are in both. The probability is $\\frac{47}{208}$. The answer $\\frac{47}{340}$ uses the total school population instead of the restricted set of sport-or-music students. The answer $\\frac{47}{255}$ adds $142 + 113 = 255$ without subtracting the overlap, double-counting students in both activities. The answer $\\frac{47}{162}$ results from an arithmetic error in the inclusion-exclusion calculation, such as computing $142 + 113 - 47$ as $162$ instead of $208$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZTEE25', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A pollster wants to estimate the proportion of adults in a state who support a policy change. A pilot study suggests the proportion is near $0.40$. The pollster wants the margin of error to be at most $\\pm 3\\%$ at a $95\\%$ confidence level, using $z^* = 1.96$. Using the formula $n = \\frac{(z^*)^2 \\cdot \\hat{p}(1-\\hat{p})}{E^2}$, which of the following is closest to the minimum sample size needed?', NULL, $lyceon_json$[{"key":"A","text":"$267$"},{"key":"B","text":"$683$"},{"key":"C","text":"$1{,}025$"},{"key":"D","text":"$1{,}068$"}]$lyceon_json$::jsonb, 'C', NULL, E'Using $n = \\frac{(1.96)^2 \\cdot 0.40 \\cdot 0.60}{(0.03)^2} = \\frac{3.8416 \\cdot 0.24}{0.0009} = \\frac{0.921984}{0.0009} \\approx 1024.4$. Rounding up to ensure the margin of error does not exceed $3\\%$ gives $n = 1{,}025$. The answer $267$ results from using $E = 0.06$ (doubling the margin of error) or misapplying the formula. The answer $683$ comes from using $\\hat{p}(1-\\hat{p}) = 0.40 \\cdot 0.40 = 0.16$ instead of $0.40 \\cdot 0.60 = 0.24$. The answer $1{,}068$ results from using $\\hat{p} = 0.50$ (maximum variability) instead of the pilot estimate $\\hat{p} = 0.40$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20I0GQ1', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief introduction about glassblower Tomoko Senda for a community arts newsletter. The student wants to emphasize the range of Senda''s work. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20OS93K', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Having analyzed over fourteen thousand soil samples collected from high-altitude peat bogs in the ______ concluded that permafrost in the region had begun thawing at least two decades earlier than prevailing climate models had predicted.', $lyceon_json$[{"key":"A","text":"Andes, the geochemistry team"},{"key":"B","text":"Andes, the soil samples"},{"key":"C","text":"Andes, it was concluded that researchers"},{"key":"D","text":"Andes, the findings"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice is "the geochemistry team" because the participial phrase "Having analyzed over fourteen thousand soil samples" must be followed by the noun that performed the action of analyzing. Only a research team can analyze soil samples, making "the geochemistry team" the logical and grammatically correct subject. The option "the soil samples" creates a dangling modifier because soil samples cannot analyze themselves. The option using "it was concluded that researchers" shifts to a passive construction that leaves the participial phrase without a proper subject and restructures the sentence incoherently. The option "the findings" also creates a dangling modifier because findings do not perform the action of analyzing samples.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20V83ZN', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The fennec fox, native to the Sahara Desert, has evolved unusually large ears that serve a dual purpose. The ears dissipate excess body ______ they also provide exceptional hearing, allowing the fox to detect prey moving beneath the sand.', $lyceon_json$[{"key":"A","text":"heat, they"},{"key":"B","text":"heat they"},{"key":"C","text":"heat, and"},{"key":"D","text":"heat and,"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice uses a comma followed by the coordinating conjunction "and" to join two independent clauses: "The ears dissipate excess body heat" and "they also provide exceptional hearing." The option using only a comma before "they" creates a comma splice, which incorrectly joins two independent clauses with just a comma. The option with no punctuation before "they" produces a run-on sentence. The option placing the comma after "and" rather than before it mispositions the required punctuation for joining independent clauses with a coordinating conjunction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW238VTWC', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Marine biologist Sylvia Gerhardt observed that the symbiotic relationship between cleaner wrasses and larger reef fish had become increasingly _______ in areas affected by coral bleaching. Where the reef structure deteriorated, the wrasses lost their cleaning stations, and the larger fish, deprived of parasite removal services, began migrating to healthier reef zones.', $lyceon_json$[{"key":"A","text":"tenuous"},{"key":"B","text":"arbitrary"},{"key":"C","text":"fraudulent"},{"key":"D","text":"redundant"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a relationship weakening due to environmental degradation—the wrasses lose stations and the larger fish leave. "Tenuous" means weak or slight, accurately capturing how the symbiotic bond is breaking down. "Arbitrary" means based on random choice rather than reason, which does not describe the degradation of a biological relationship. "Fraudulent" means obtained through deception, which is incoherent when describing a symbiotic ecological relationship. "Redundant" means no longer needed or superfluous, but the passage indicates the relationship is still needed—it is simply becoming harder to maintain, not unnecessary.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24RR5YP', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if true, would most directly weaken the ecologists'' claim?', E'Ecologists studying monarch butterfly populations in central Mexico have claimed that the sharp decline in overwintering colonies since 2015 is primarily attributable to the loss of milkweed habitat along the butterflies'' migratory corridor in the midwestern United States. They point to satellite data showing a 38 percent reduction in milkweed coverage across Iowa, Missouri, and Illinois between 2010 and 2022. However, some researchers have questioned whether other factors might be equally or more important.', $lyceon_json$[{"key":"A","text":"A long-term dataset shows that winter storm frequency in the mountains of central Mexico has increased by 47 percent since 2012, and colony sizes drop sharply in years following severe storms."},{"key":"B","text":"Milkweed coverage in Kansas and Nebraska also declined during the same period, extending the geographic scope of the habitat loss."},{"key":"C","text":"Monarch butterflies have been observed using alternative host plants when milkweed is unavailable, but their larvae develop more slowly on these substitutes."},{"key":"D","text":"Conservation groups in Iowa have begun planting milkweed corridors along highway medians to offset agricultural habitat loss."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the finding about increased winter storm frequency in Mexico correlating with colony declines. This directly weakens the ecologists'' claim that milkweed loss is the primary cause by presenting a competing explanation with its own quantitative support. The finding about milkweed loss in Kansas and Nebraska actually strengthens the ecologists'' claim by showing the problem is even more widespread. The finding about alternative host plants partially addresses milkweed dependence but does not identify a competing cause for the population decline. The finding about conservation planting describes a remediation effort and provides no evidence about the cause of the decline.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25RM9X5', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Coral reefs in the western Pacific have long been studied for their biodiversity, but marine biologist Anya Petrov has shifted attention to an overlooked aspect: the acoustic environment. By deploying underwater microphones across seventeen reef sites near Palau, Petrov documented that healthy reefs produce a dense, continuous soundscape dominated by snapping shrimp and fish vocalizations. Degraded reefs, by contrast, are markedly quieter. Petrov argues that acoustic monitoring could serve as a rapid, low-cost method for assessing reef health without requiring the labor-intensive visual surveys currently used.', $lyceon_json$[{"key":"A","text":"Petrov proposes that sound recordings offer a practical alternative to visual surveys for evaluating reef condition."},{"key":"B","text":"Petrov discovered that snapping shrimp are the primary contributors to noise on healthy coral reefs."},{"key":"C","text":"Marine biologists have traditionally ignored the biodiversity of coral reefs in the western Pacific."},{"key":"D","text":"Degraded coral reefs near Palau support fewer fish species than healthy reefs do."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that Petrov proposes sound recordings as a practical alternative to visual surveys for evaluating reef condition. The passage introduces Petrov''s focus on the acoustic environment of reefs and concludes with her argument that acoustic monitoring could replace labor-intensive visual surveys. The choice about snapping shrimp isolates one detail rather than capturing the passage''s central claim. The choice about marine biologists ignoring biodiversity contradicts the passage, which says reefs have long been studied for biodiversity. The choice about fewer fish species on degraded reefs introduces a claim the passage never makes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26AD6JH', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare manuscripts housed in the university''s underground vault ______ a team of conservators who monitor temperature and humidity levels around the clock to prevent deterioration of the fragile documents.', $lyceon_json$[{"key":"A","text":"requires"},{"key":"B","text":"require"},{"key":"C","text":"are requiring"},{"key":"D","text":"have required"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice is "requires" because the subject of the sentence is the singular noun "collection," not the plural "manuscripts" in the intervening prepositional phrase. A singular subject takes a singular verb. The option "require" incorrectly uses a plural verb form, likely because of attraction to the nearby plural noun "manuscripts." The option "are requiring" uses a plural progressive form, which also fails to agree with the singular subject. The option "have required" uses a plural perfect form, again mismatching the singular "collection."', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26H3MDN', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although archaeologists have long debated whether the Minoan civilization of ancient Crete developed a true written language independently or adopted one from neighboring ______ recent analysis of clay tablets unearthed at Phaistos suggests that the Minoans created their script without significant external influence, overturning decades of scholarly consensus.', $lyceon_json$[{"key":"A","text":"cultures. Recent"},{"key":"B","text":"cultures, recent"},{"key":"C","text":"cultures; therefore, recent"},{"key":"D","text":"cultures; recent"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice uses a comma after "cultures" to properly close the introductory dependent clause beginning with "Although" before the independent clause that follows. The "Although" clause is subordinate and cannot stand alone as a sentence. The option using a period after "cultures" severs the dependent clause from the independent clause, creating a sentence fragment beginning with "Although." The option using a semicolon with "therefore" similarly fragments the dependent clause on the left side of the semicolon, and "therefore" incorrectly implies that the independent clause is a logical consequence of the debate rather than a new finding about it. The option using a semicolon alone also creates a fragment from the dependent clause, since a semicolon requires independent clauses on both sides.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28P9R59', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The grant proposal outlined three primary objectives for the five-year study: cataloging previously undocumented fungal species in temperate rainforests, ______ and developing protocols for cultivating the most promising specimens in laboratory conditions.', $lyceon_json$[{"key":"A","text":"an assessment of their potential applications in pharmaceutical research,"},{"key":"B","text":"to assess their potential applications in pharmaceutical research,"},{"key":"C","text":"they assessed their potential applications in pharmaceutical research,"},{"key":"D","text":"assessing their potential applications in pharmaceutical research,"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct choice is "assessing their potential applications in pharmaceutical research" because the sentence presents a list of three objectives introduced by a colon, each stated as a gerund phrase: "cataloging," the blank, and "developing." Parallel structure requires all three items to use the same grammatical form. The option "an assessment of" breaks parallelism by substituting a noun phrase for the gerund pattern. The option "to assess" breaks parallelism by using an infinitive instead of a gerund. The option "they assessed" breaks parallelism entirely by introducing an independent clause with a subject and finite verb into a list of gerund phrases.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29GVYP3', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Glaciologist Dr. Amara Osei has documented an alarming trend in her twenty-three years of fieldwork on the Quelccaya Ice Cap in ______ the glacier has retreated by nearly 1,100 meters since she began her measurements, a rate of decline that exceeds all previous projections.', $lyceon_json$[{"key":"A","text":"Peru,"},{"key":"B","text":"Peru; nevertheless,"},{"key":"C","text":"Peru, which"},{"key":"D","text":"Peru:"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct choice uses a colon after "Peru" to introduce the specific evidence that elaborates on the "alarming trend" mentioned in the first clause. A colon is appropriate here because the second clause directly explains and specifies the claim in the first. The option using only a comma creates a comma splice between two independent clauses. The option using a semicolon with "nevertheless" employs a conjunctive adverb that signals contrast or concession, but the second clause provides supporting evidence for the alarming trend rather than contrasting with it. The option using "which" produces a grammatically incoherent construction because "which" cannot logically refer to "Peru" in this context and fails to introduce the clause about the glacier''s retreat.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29SGE13', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Agricultural economists at the University of Ghana hypothesize that smallholder cassava farmers who receive weekly text-message alerts about regional market prices sell their harvests at higher prices than farmers who rely on word-of-mouth price information. The economists designed a randomized trial in which 340 cassava farmers in the Volta Region were divided into a treatment group receiving the alerts and a control group that did not.', $lyceon_json$[{"key":"A","text":"Farmers in the treatment group sold their cassava at prices averaging 14 percent higher than those obtained by the control group."},{"key":"B","text":"Farmers in both groups reported feeling more confident about their selling decisions after the trial ended."},{"key":"C","text":"The treatment group planted a larger area of cassava in the following growing season than the control group did."},{"key":"D","text":"Most farmers in the control group already had access to mobile phones capable of receiving text messages."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the finding that treatment-group farmers sold cassava at prices averaging 14 percent higher than the control group. The hypothesis specifically predicts higher selling prices for farmers receiving alerts, so a direct price comparison between groups is the most relevant evidence. The finding about confidence addresses farmer attitudes rather than actual selling prices. The finding about planting area concerns future production decisions, not current selling prices. The finding about phone access describes the control group''s capacity to receive messages but says nothing about whether the alerts affected prices.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2B4P3P5', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'In her 2019 monograph on peasant revolts in fourteenth-century Flanders, historian Maren Kolthoff argues that the uprisings were not spontaneous eruptions of anger but rather _______ campaigns: rebel leaders circulated pamphlets weeks in advance, coordinated supply lines across multiple villages, and timed their marches to coincide with seasonal labor shortages that would maximize economic disruption to the landowning class.', $lyceon_json$[{"key":"A","text":"calculated"},{"key":"B","text":"theatrical"},{"key":"C","text":"sporadic"},{"key":"D","text":"punitive"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage contrasts the revolts with "spontaneous eruptions" and then provides evidence of advance planning: pamphlets circulated weeks ahead, coordinated supply lines, and strategic timing. "Calculated" means carefully planned and thought out, which precisely captures this deliberate orchestration. "Theatrical" means dramatic or exaggerated for effect, but the passage emphasizes strategic planning, not performative display. "Sporadic" means occurring at irregular intervals, which would align with "spontaneous" rather than contrast it as the passage requires. "Punitive" means intended as punishment; while the revolts targeted landowners, the blank describes the nature of the campaigns'' organization, not their intent to punish.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CNE07E', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'Historians have generally attributed the decline of the Aksumite Empire in the seventh century to the expansion of Islamic trade networks that bypassed Aksum''s Red Sea ports. However, geoarchaeologist Desta Mekonnen presents evidence from sediment cores taken at three sites in northern Ethiopia suggesting that prolonged soil erosion, driven by centuries of intensive agriculture, degraded the region''s capacity to support its urban population. Mekonnen acknowledges that shifting trade routes compounded the crisis but contends that environmental deterioration was the underlying vulnerability that made Aksum unable to adapt to external economic pressures.', $lyceon_json$[{"key":"A","text":"Mekonnen argues that environmental degradation, rather than trade disruption alone, was the fundamental cause of Aksum's decline."},{"key":"B","text":"The expansion of Islamic trade networks had no significant effect on the Aksumite Empire's economy."},{"key":"C","text":"Sediment cores from northern Ethiopia prove that Aksumite agriculture was more advanced than historians previously believed."},{"key":"D","text":"Mekonnen's research contradicts all previous scholarship on the reasons for the Aksumite Empire's decline."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that Mekonnen argues environmental degradation was the fundamental cause of Aksum''s decline. The passage presents Mekonnen''s sediment-core evidence and his contention that environmental deterioration was the ''underlying vulnerability,'' while acknowledging trade shifts as a compounding factor. The choice claiming trade networks had no significant effect misreads the passage, since Mekonnen acknowledges trade routes compounded the crisis. The choice about agriculture being more advanced than believed distorts the sediment-core evidence, which concerns soil erosion, not agricultural sophistication. The choice claiming Mekonnen contradicts all previous scholarship overstates his position; he supplements, rather than wholly replaces, the trade-route explanation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D9K8ME', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would Delvecchio and colleagues (Text 2) most likely respond to Castellano''s argument in Text 1?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FXEA3R', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Neuroscientist Clara Lindqvist investigated whether the brain processes literal and metaphorical uses of temperature language differently. She used functional MRI to scan participants as they read sentences like "the soup was warm" (literal) and "the welcome was warm" (metaphorical). Both sentence types activated the left inferior frontal gyrus, a region associated with semantic processing. However, only the literal sentences additionally activated the somatosensory cortex, which processes physical temperature sensations. Lindqvist argues that this dissociation undermines the strong version of embodied cognition theory, which holds that understanding any use of a sensory word requires mentally simulating the corresponding sensation, because ________', $lyceon_json$[{"key":"A","text":"metaphorical temperature language was processed without engaging the brain region responsible for physical temperature sensation, indicating that sensory simulation is not required for comprehending figurative uses."},{"key":"B","text":"literal temperature language activated fewer brain regions overall than metaphorical temperature language did."},{"key":"C","text":"the left inferior frontal gyrus is known to be involved in motor planning as well as semantic processing."},{"key":"D","text":"participants reported that they found the metaphorical sentences more difficult to understand than the literal sentences."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that metaphorical temperature language was processed without engaging the somatosensory cortex, indicating sensory simulation is not required for figurative comprehension. Strong embodied cognition predicts that even metaphorical uses would activate sensory regions; the absence of somatosensory activation during metaphorical processing directly contradicts that prediction. The choice claiming literal sentences activated fewer regions than metaphorical ones contradicts the passage, which shows literal sentences activated an additional region. The choice about the left inferior frontal gyrus and motor planning introduces information irrelevant to the dissociation between literal and metaphorical processing. The choice about participants finding metaphorical sentences harder introduces self-report data the passage never mentions and does not address the neural dissociation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2G1O25P', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'In a 2023 study, cognitive scientist Lena Farkas investigated whether bilingual individuals switch problem-solving strategies more readily than monolinguals when an initial approach fails. Participants attempted a series of puzzles that required shifting from a formulaic method to an insight-based one partway through. Farkas found that bilinguals did not solve the puzzles faster overall, but they abandoned unproductive strategies significantly sooner. She interprets this finding as evidence that habitual language switching trains a domain-general cognitive flexibility — not enhanced intelligence or creativity, but a narrower capacity to disengage from ineffective routines.', $lyceon_json$[{"key":"A","text":"Farkas's study suggests bilingualism fosters a specific cognitive flexibility related to abandoning ineffective strategies rather than broadly superior problem-solving ability."},{"key":"B","text":"Farkas's research demonstrates that bilingual individuals are more creative than monolinguals when solving insight-based puzzles."},{"key":"C","text":"Bilingual participants in Farkas's study solved puzzles faster than monolingual participants because of their experience with language switching."},{"key":"D","text":"Farkas concludes that the cognitive benefits of bilingualism have been overstated by previous researchers."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating Farkas''s study suggests bilingualism fosters a specific cognitive flexibility related to abandoning ineffective strategies rather than broadly superior problem-solving. The passage explicitly distinguishes a ''narrower capacity to disengage from ineffective routines'' from enhanced intelligence or creativity. The choice about bilinguals being more creative contradicts the passage''s explicit exclusion of creativity as an explanation. The choice about solving puzzles faster directly contradicts the finding that bilinguals ''did not solve the puzzles faster overall.'' The choice about cognitive benefits being overstated introduces a claim Farkas never makes; she refines the nature of the benefit rather than dismissing it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HPIS2N', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The axolotl, a salamander endemic to Lake Xochimilco near Mexico City, possesses an extraordinary ability to regenerate entire ______ most other vertebrates can only form scar tissue after sustaining comparable injuries.', $lyceon_json$[{"key":"A","text":"limbs, however,"},{"key":"B","text":"limbs, but"},{"key":"C","text":"limbs but"},{"key":"D","text":"limbs however"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice uses a comma followed by the coordinating conjunction "but" to properly join two contrasting independent clauses. The option using "however" with commas creates a comma splice because "however" is a conjunctive adverb, not a coordinating conjunction, and cannot join independent clauses with only a comma. The option omitting the comma before "but" violates the convention requiring a comma before a coordinating conjunction that joins two independent clauses. The option using "however" with no preceding semicolon or period produces a run-on sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I1JBOX', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two texts?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IAJEG0', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the third sentence in the overall structure of the text?', E'The fruit of the New Zealand kiwifruit vine was originally marketed in the United States under the name "Chinese gooseberry." Importers soon discovered, however, that American consumers associated gooseberries with tartness and avoided the product. In 1959, the fruit was rebranded as "kiwifruit" after New Zealand''s national bird, and sales rose sharply within a single growing season.', $lyceon_json$[{"key":"A","text":"It presents the outcome of a strategy adopted to address the problem identified in the second sentence."},{"key":"B","text":"It provides a scientific explanation for why the fruit's flavor profile changed over time."},{"key":"C","text":"It introduces a new controversy about agricultural naming conventions."},{"key":"D","text":"It questions whether the original marketing approach was intentionally misleading."}]$lyceon_json$::jsonb, 'A', NULL, E'The second sentence identifies a marketing problem (consumers avoided the product due to the name''s association with tartness), and the third sentence describes how the fruit was renamed and that sales then rose—presenting the resolution. The claim about a scientific explanation for flavor change is incoherent because the passage discusses branding, not the fruit''s actual flavor. The passage presents no controversy about naming conventions; it describes a straightforward business decision. The passage never suggests the original marketing was deceptive—it simply notes the name was unsuccessful.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IOAORV', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'Linguist Hana Pokorná has documented that speakers of Czech who emigrated to Argentina in the 1930s gradually replaced certain Czech vowel sounds with their closest Spanish equivalents. Pokorná recorded forty-seven such emigrants in Buenos Aires between 2004 and 2011 and found that the degree of phonetic shift correlated strongly with the age at which each speaker had arrived: those who emigrated before age twelve showed nearly complete adoption of Spanish vowel qualities, while those who arrived as adults retained most Czech distinctions even after seventy years abroad.', $lyceon_json$[{"key":"A","text":"It introduces a researcher's finding and then presents data that reveals a key variable influencing the observed phenomenon."},{"key":"B","text":"It proposes a hypothesis about language loss and then describes an experiment that disproved it."},{"key":"C","text":"It summarizes a debate among linguists and then sides with one position over another."},{"key":"D","text":"It defines a technical term in phonetics and then provides examples to clarify the definition."}]$lyceon_json$::jsonb, 'A', NULL, E'The first sentence introduces Pokorná''s finding (Czech emigrants adopted Spanish vowel sounds), and the second sentence presents her recorded data showing that age of arrival was the key variable. The text does not describe a disproved hypothesis—the data supports and refines the initial finding rather than contradicting it. No debate or opposing positions are mentioned; only one researcher''s work is discussed. The passage does not define a technical term; it describes an observed phonetic shift without formally defining terminology.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J7A6YU', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a research summary about the health effects of urban tree canopy for a public policy course. The student wants to present a finding and acknowledge a limitation of the study. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2K2AZKK', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeometallurgist Yuki Tanabe analyzed copper slag deposits at a ninth-century smelting site in southern Hokkaido and found unusually high arsenic concentrations, suggesting the ore came from a deposit over 400 kilometers to the north. Previous researchers had attributed the site''s copper artifacts to local ore bodies. ______ Tanabe''s geochemical fingerprinting reveals that the community maintained long-distance trade networks far earlier than the regional chronology had assumed.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"On the contrary,"},{"key":"D","text":"Furthermore,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage sets up a direct contradiction: previous researchers believed the copper was local, but Tanabe''s evidence shows it traveled over 400 kilometers, indicating long-distance trade networks. "On the contrary," correctly signals that Tanabe''s finding directly opposes the prior attribution. "In other words," wrongly suggests the final sentence merely restates the preceding claim rather than contradicting it. "Nevertheless," implies a concession—that despite something, the conclusion still holds—but the passage does not present an obstacle to Tanabe''s conclusion; it presents a prior view that her evidence overturns. "Furthermore," wrongly treats Tanabe''s finding as an additional supporting point rather than a correction of the previous interpretation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LT1GCK', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Entomologist Dara Ngale has spent over a decade cataloging beetle species in the montane forests of central Cameroon. Her recent survey identified thirty-seven species previously unknown to science. ______ Ngale''s discoveries have prompted the Cameroonian government to designate two new protected forest corridors in the region.', $lyceon_json$[{"key":"A","text":"As a result,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"For instance,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes Ngale''s discoveries of unknown beetle species and then states that the government created protected forest corridors. The second sentence is a consequence of the first, so a cause-and-effect transition is needed. "As a result," correctly signals this causal relationship. "In contrast," wrongly implies opposition between the discoveries and the government response. "For instance," wrongly treats the government action as an example of the discoveries rather than a consequence. "Meanwhile," wrongly implies the events are merely simultaneous rather than causally connected.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MF5FUK', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Cognitive scientist Elara Mubarak tested whether bilingual speakers of Swahili and Dutch experience different color-discrimination thresholds depending on which language context they are primed in. She found that participants primed in Swahili distinguished shades of green more quickly, consistent with Swahili''s richer set of green-related color terms. Participants primed in Dutch, by contrast, showed faster discrimination among shades of blue. ______ the advantage each language conferred was limited to the region of color space where that language makes finer lexical distinctions.', $lyceon_json$[{"key":"A","text":"That is,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"In addition,"},{"key":"D","text":"Granted,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence following the blank restates and synthesizes the two preceding findings—Swahili priming helped with greens, Dutch priming helped with blues—into a single generalization: each language''s advantage was limited to the color region where it has finer vocabulary. "That is," correctly signals a clarifying restatement. "Consequently," wrongly implies the generalization is a new result caused by the findings rather than a restatement of what they jointly show. "In addition," wrongly treats the generalization as new, separate information rather than a summary of the same data. "Granted," wrongly introduces the generalization as a concession the author is acknowledging before presenting a counterpoint, but no counterpoint follows.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NNZRJY', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Galápagos Marine Reserve, one of the largest protected ocean areas in the world, supports an extraordinary diversity of species. ______ unique ecosystem includes marine iguanas that dive to feed on algae, flightless cormorants that have traded flight for superior swimming ability, and penguins that thrive despite living near the equator.', $lyceon_json$[{"key":"A","text":"It's"},{"key":"B","text":"Their"},{"key":"C","text":"Its"},{"key":"D","text":"There"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice is "Its" because the sentence requires a singular possessive pronoun referring to the Galápagos Marine Reserve. "Its" is the possessive form of "it," correctly indicating that the ecosystem belongs to the Reserve. The option "It''s" is a contraction of "it is," which produces the ungrammatical construction "It is unique ecosystem includes." The option "Their" uses a plural possessive pronoun, but the antecedent "Reserve" is singular. The option "There" is an adverb indicating location, not a possessive pronoun, and produces a nonsensical construction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NQLH3I', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a comparative analysis for a music history seminar. The student wants to highlight a similarity between two composers'' approaches while noting a key difference in their outcomes. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NYT6HZ', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which quotation from a literary scholar would, if accurate, most directly support the claim presented in the text?', E'Some literary critics have argued that Nella Larsen''s 1929 novel Passing is primarily a narrative about racial identity in America. Scholar Fiona Obeng-Darko challenges this reading, contending that the novel''s central preoccupation is not race per se but the instability of social performance itself. In Obeng-Darko''s view, Larsen uses the motif of racial passing to explore how all identities — class, gender, sexuality — are constructed through repeated acts of presentation that can always be disrupted.', $lyceon_json$[{"key":"A","text":"\"Larsen's deployment of the passing motif functions as a metonym for the performative constitution of identity categories well beyond race, destabilizing the assumption that any social role is ontologically fixed.\""},{"key":"B","text":"\"The enduring significance of Passing lies in its unflinching depiction of the psychological costs that African Americans faced when concealing their racial heritage in the early twentieth century.\""},{"key":"C","text":"\"Larsen's novel is best understood as a sociological document recording the material conditions of Black life in 1920s Chicago and New York.\""},{"key":"D","text":"\"While Passing addresses themes of performance, Larsen ultimately reaffirms the primacy of racial identity by punishing her protagonist for transgressing racial boundaries.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the quotation describing Larsen''s passing motif as a metonym for the performative constitution of identity categories beyond race. This directly supports Obeng-Darko''s claim that the novel''s central concern is the instability of social performance across multiple identity categories, not race alone. The quotation about psychological costs of concealing racial heritage supports the traditional racial-identity reading that Obeng-Darko challenges. The quotation about a sociological document focuses on material conditions rather than performative identity, aligning with neither the traditional reading nor Obeng-Darko''s. The quotation acknowledging performance but reaffirming racial primacy actually contradicts Obeng-Darko''s argument by asserting that race remains the novel''s dominant concern.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OFEQXZ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The brown-headed cowbird is a brood parasite: it lays its eggs in the nests of other bird species and relies on the host parents to raise its young. Ornithologist Rajiv Chandran studied 53 nests of the eastern phoebe that had been parasitized by cowbirds and found that phoebes whose nests contained cowbird eggs spent 19 percent more time foraging than phoebes with unparasitized nests. Because cowbird chicks are larger and more demanding than phoebe chicks, this finding suggests that ________', $lyceon_json$[{"key":"A","text":"host parents increase their foraging effort to meet the greater food demands imposed by cowbird chicks."},{"key":"B","text":"cowbird chicks learn to forage independently earlier than phoebe chicks do."},{"key":"C","text":"eastern phoebes can distinguish cowbird eggs from their own eggs but choose not to remove them."},{"key":"D","text":"brown-headed cowbirds preferentially parasitize the nests of phoebes that are already strong foragers."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that host parents increase foraging effort to meet the greater food demands imposed by cowbird chicks. The passage establishes that cowbird chicks are larger and more demanding and that parasitized phoebes forage 19 percent more; the most direct inference is that the increased demand drives the increased foraging. The choice about cowbird chicks foraging independently introduces behavior not addressed by the passage. The choice about phoebes distinguishing eggs addresses nest recognition, which is unrelated to the foraging data. The choice about cowbirds targeting strong foragers reverses the causal direction suggested by the evidence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SCVWTG', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Which choice best describes how Engström''s argument in Text 2 relates to al-Rashid''s argument in Text 1?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TML1Q1', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes how Mavraki''s argument is structured in the text?', E'Many scholars have attributed the collapse of the Late Bronze Age civilizations around 1177 BCE to the so-called Sea Peoples—raiders who supposedly destroyed the Hittite, Mycenaean, and other eastern Mediterranean states in a swift military onslaught. Archaeologist Eleni Mavraki contends, however, that the material evidence tells a more complicated story. Destruction layers at coastal sites do show burning consistent with raids, Mavraki concedes, but inland cities like Hattusa exhibit gradual depopulation over decades rather than sudden catastrophe. She argues that drought-driven agricultural failure destabilized these kingdoms from within, making them vulnerable to opportunistic raiding that was a symptom of collapse rather than its cause.', $lyceon_json$[{"key":"A","text":"It acknowledges evidence that partially supports the prevailing view and then reinterprets the broader pattern to propose an alternative causal explanation."},{"key":"B","text":"It dismisses the archaeological record as unreliable and substitutes a theoretical model based on climate science."},{"key":"C","text":"It accepts the Sea Peoples theory in full and adds an additional factor to strengthen it."},{"key":"D","text":"It compares two competing archaeological methodologies and argues that one produces more accurate dating of destruction events."}]$lyceon_json$::jsonb, 'A', NULL, E'Mavraki concedes that coastal burning is consistent with raids (acknowledging partial support for the prevailing view) but then points to inland gradual depopulation as evidence that drought-driven agricultural failure was the primary cause, reframing the raids as a symptom rather than the cause. The claim that she dismisses the archaeological record is wrong—she explicitly engages with destruction layers and depopulation evidence. She does not accept the Sea Peoples theory in full; she challenges it by arguing that raiding was a symptom, not the cause, of collapse. The passage does not discuss or compare archaeological methodologies; it concerns competing causal explanations for the collapse.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VLHY0U', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'The architect''s proposal for the new library was met with widespread approval from the city council. Members praised the design for its elegant simplicity, noting that the blueprint managed to _______ the building''s functional requirements with an aesthetic vision that complemented the surrounding historic district.', $lyceon_json$[{"key":"A","text":"reconcile"},{"key":"B","text":"neglect"},{"key":"C","text":"fracture"},{"key":"D","text":"postpone"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a design that successfully combines functional needs with aesthetic vision, so "reconcile" fits because it means to bring two things into harmony. "Neglect" means to fail to attend to, which contradicts the passage''s positive tone. "Fracture" means to break apart, the opposite of combining elements successfully. "Postpone" means to delay to a later time, which makes no sense in the context of combining requirements with a vision.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VZLJFA', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Archaeologist Miriam Osei has documented that ceramic workshops in the ancient Malian city of Djenné-Djenno produced two distinct types of pottery: coarse, thick-walled storage vessels and thin, elaborately decorated serving ware. Chemical analysis of the clay used in each type reveals that the storage vessels were made from locally sourced riverbank clay, while the serving ware used a finer kaolin clay available only from deposits 130 kilometers to the northeast. The presence of the kaolin-based serving ware at Djenné-Djenno therefore suggests that ________', $lyceon_json$[{"key":"A","text":"the city's potters maintained trade connections or procurement networks extending well beyond the immediate river valley."},{"key":"B","text":"the storage vessels were considered less valuable than the serving ware by the city's inhabitants."},{"key":"C","text":"kaolin clay produces more durable ceramics than riverbank clay under all firing conditions."},{"key":"D","text":"Djenné-Djenno's ceramic workshops exported their products to settlements near the kaolin deposits."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice about potters maintaining trade connections or procurement networks extending beyond the immediate river valley. Since the kaolin clay was available only 130 kilometers away and was used locally in Djenné-Djenno, the city''s workshops must have had some means of obtaining materials from that distant source. The choice about storage vessels being considered less valuable may be plausible but is not supported by the chemical analysis data presented. The choice about kaolin durability makes a universal material-science claim the passage does not address. The choice about exporting ceramics to the kaolin source reverses the direction of material flow described in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WLUHIH', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Restoration ecologists working in the Scottish Highlands have long relied on deer-fencing to protect native saplings from grazing. Fenced enclosures allow birch and rowan seedlings to grow past the vulnerable browsing height within three to five years. ______ the fences fragment habitat for ground-nesting birds such as black grouse, whose chicks cannot cross the wire barriers during their first weeks of life.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"However,"},{"key":"C","text":"Accordingly,"},{"key":"D","text":"Specifically,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage presents a benefit of deer-fencing (protecting saplings) and then introduces a drawback (fragmenting habitat for ground-nesting birds). This contrast requires a transition signaling an opposing idea. "However," correctly marks this shift from advantage to disadvantage. "Similarly," wrongly implies the second point agrees with or parallels the first. "Accordingly," wrongly suggests the habitat fragmentation is a logical or intended consequence of the fencing goal. "Specifically," wrongly frames the bird-habitat problem as a more detailed restatement of the sapling-protection point.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original"